        if (st === 'approved' && a.deposit > 0 && d !== 'paid') throw new Error('Mark the deposit as received before approving this bidder.'); if (['rejected', 'suspended'].includes(st) && (!note || note.length < 3)) throw new Error('Write a short reason for the bidder.'); if (['refunded', 'forfeited'].includes(d) && (!reason || reason.length < 3)) throw new Error('Please give a reason for the deposit decision (kept in the audit log).');
