    const groups = { live: ax.list.filter((a) => a.phase === 'live' || a.phase === 'closing'), closing: ax.list.filter((a) => a.phase === 'closing'), upcoming: ax.list.filter((a) => a.phase === 'upcoming'), completed: ax.list.filter((a) => ['provisional', 'sold', 'reserve_not_met', 'ended'].includes(a.phase)) };
    const T = [['live', 'Live now'], ['closing', 'Closing soon'], ['upcoming', 'Upcoming'], ['completed', 'Completed']];
    const list = groups[ax.tab] || [];
