    let a = null; try { a = await AU.state(id); } catch (err) { host.innerHTML = `<div class="admin-empty">${esc(err.message)}</div>`; return; }
    if (!a) { host.innerHTML = '<div class="admin-empty">This auction is not available.</div>'; return; }
