  async function auAdminLoad() {
    ax.loadedAt = Date.now();
    try { ax.admin = await AU.admin(); } catch (err) { ax.admin = { error: err.message }; }
    if (admin.el && !admin.el.hidden && admin.tab === 'auctions') { const body = ($('.ax-body', admin.el) || $('.admin-content', admin.el)); if (body) { const open = $$('details[open][data-k]', body).map((x) => x.dataset.k); const y = admin.el.scrollTop; const typed = $$('[data-ax-keep]', body).map((x) => [x.dataset.axKeep, x.value]); body.innerHTML = auAdminHTML(); open.forEach((k) => { const d = $(`details[data-k="${CSS.escape(k)}"]`, body); if (d) d.open = true; }); typed.forEach(([k, v]) => { const i = $(`[data-ax-keep="${CSS.escape(k)}"]`, body); if (i) i.value = v; }); admin.el.scrollTop = y; auTick(); } }
  }
  const dtl = (t) => { if (!t) return ''; const d = new Date(t); return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 16); };
  function auAdminHTML() {
    const d = ax.admin; if (!d) { auAdminLoad(); return '<div class="admin-empty">Loading…</div>'; } if (d.error) return `<div class="admin-empty">${esc(d.error)}</div>`;
    const active = (a) => ['requested', 'upcoming', 'live', 'closing', 'ended', 'provisional', 'reserve_not_met'].includes(a.phase); const list = d.filter((a) => ax.adminFilter === 'active' ? active(a) : !active(a));
    return `<div class="gwa"><div class="admin-head-row"><div><div class="eyebrow"><span></span> AUCTIONS</div><h2>Auction management</h2><p class="admin-sub">Approve requests and set the rules, approve bidders and confirm deposits, watch bids live, void a bid with a reason, and record the result. Rules lock once bidding starts. Every action is in the audit log.</p></div><button type="button" class="admin-refresh" data-axa="reload">${DI(DIC.trend, 15)} Refresh</button></div>
      <div class="gw-filter"><div class="seg">${[['active', `Active (${d.filter(active).length})`], ['done', `Completed / cancelled (${d.filter((a) => !active(a)).length})`]].map(([k, t]) => `<button type="button" data-axa="filter" data-v="${k}" class="${ax.adminFilter === k ? 'active' : ''}">${esc(t)}</button>`).join('')}</div></div>
      ${list.length ? list.map((a) => { const locked = !['requested', 'upcoming'].includes(a.phase) || a.bid_count > 0; const k = esc(a.id); return `<details class="urg-adm" data-k="${k}" ${list.length === 1 ? 'open' : ''}><summary><div><b>${esc(a.title || '')}</b><small>${esc(a.ref)} · ${esc(a.area || '')}, ${esc(a.city || '')} · start ${esc(rs(a.starting_price))}${a.reserve_price ? ' · reserve ' + esc(rs(a.reserve_price)) : ''} · ${a.high_amount ? 'high ' + esc(rs(a.high_amount)) + ' · ' : ''}${esc(a.bid_count)} bids · ${esc(a.bidder_list.length)} bidders</small></div><span class="ax-sumr">${['live', 'closing', 'upcoming'].includes(a.phase) ? auClock(a) : ''}${auChip(a.phase)}</span></summary>
        <div class="urg-adm-body">
          <div class="urg-grid"><div><h4>Seller</h4><p>${esc(a.seller || '')} ${a.seller_id_verified ? '<span class="id-chip">ID verified</span>' : '<small>(identity not verified)</small>'}<br>${esc(a.seller_phone || '')} · ${esc(a.seller_email || '')}</p></div>
            <div><h4>Property</h4><p>${esc(a.listing_ref || '')} · listing ${esc(a.listing_status || '')} · asking ${esc(rs(a.listing_price))} ${a.verified ? '<span class="id-chip">RAQBO Verified</span>' : '<small>(documents not verified)</small>'}<br><button type="button" class="link-button" data-open="${esc(a.listing_id)}">View listing</button></p></div>
            <div><h4>Seller's request</h4><p>Preferred start: ${esc(a.preferred_start || 'any')} · ${esc(a.duration_days)} days<br>Inspection: ${esc(a.inspection_info || '—')}${a.seller_note ? '<br>Note: ' + esc(a.seller_note) : ''}</p></div></div>
          ${a.result_note ? `<p class="svc-note">${DI(DIC.info, 14)} <span>${esc(a.result_note)}</span></p>` : ''}
          ${['requested', 'upcoming'].includes(a.phase) ? `<form class="gwa-form" data-axa-save data-id="${k}"><fieldset ${locked ? 'disabled' : ''}><legend>Rules & schedule ${locked ? '(locked — bidding started)' : ''}</legend>
            <label><span>Starting bid (PKR)</span><input name="starting_price" type="number" min="100000" value="${esc(a.starting_price)}"></label><label><span>Reserve (PKR, private)</span><input name="reserve_price" type="number" min="0" value="${esc(a.reserve_price || '')}" placeholder="none"></label>
            <label><span>Increment (PKR)</span><input name="increment" type="number" min="1000" value="${esc(a.increment)}"></label><label><span>Bidding deposit (PKR)</span><input name="deposit" type="number" min="0" value="${esc(a.deposit)}"></label>
            <label><span>Starts</span><input name="start_at" type="datetime-local" value="${esc(dtl(a.start_at || (a.preferred_start ? a.preferred_start + 'T10:00' : '')))}"></label><label><span>Ends</span><input name="end_at" type="datetime-local" value="${esc(dtl(a.end_at || (a.preferred_start ? new Date(Date.parse(a.preferred_start + 'T21:00') + (a.duration_days - 1) * 864e5).toISOString() : '')))}"></label>
            <label><span>Late-bid window (min)</span><input name="ext_window_min" type="number" min="0" max="120" value="${esc(a.ext_window_min)}"></label><label><span>Extension (min)</span><input name="ext_min" type="number" min="0" max="120" value="${esc(a.ext_min)}"></label><label><span>Max extensions</span><input name="max_extensions" type="number" min="0" max="500" value="${esc(a.max_extensions)}"></label>
            <label><span>Buyer's premium (%)</span><input name="buyer_premium_pct" type="number" min="0" max="50" step="0.01" value="${esc(a.buyer_premium_pct)}"></label><label><span>Seller commission (%)</span><input name="seller_commission_pct" type="number" min="0" max="50" step="0.01" value="${esc(a.seller_commission_pct)}"></label>
            <label class="wide"><span>Inspection times (shown to bidders)</span><input name="inspection_info" maxlength="1000" value="${esc(a.inspection_info || '')}"></label>
            <label class="wide"><span>Special terms (shown to bidders)</span><textarea name="terms" rows="2" maxlength="6000">${esc(a.terms || '')}</textarea></label>
            <label class="wide"><span>Note to the seller</span><input name="admin_note" maxlength="1000" value="${esc(a.admin_note || '')}"></label>
            <label class="wide"><span>Audit note <small>(optional — saved in the audit log with your name and time)</small></span><input name="reason" maxlength="300" data-ax-keep="r-${k}" placeholder="${a.phase === 'requested' ? 'e.g. Documents checked and schedule agreed with the seller' : 'e.g. Seller asked to change the start date'}"></label></fieldset>
            ${locked ? '' : `<div class="button-row">${a.phase === 'requested' ? `<button type="submit" class="button button-primary" name="act" value="approve">Approve & schedule</button><button type="submit" class="button button-outline" name="act" value="reject">Reject request</button>` : '<button type="submit" class="button button-primary" name="act" value="save">Save changes</button>'}</div>`}</form>` : ''}
          <h4>Bidders (${a.bidder_list.length})</h4>${a.bidder_list.length ? `<table class="gw-table ax-bt"><thead><tr><th>No.</th><th>Member</th><th>Deposit</th><th>Status</th><th>Decision</th></tr></thead><tbody>${a.bidder_list.map((b) => `<tr data-bidder="${esc(b.id)}"><td><b>Bidder ${esc(b.no)}</b></td><td>${esc(b.name || '')}<br><small>${esc(b.phone || '')} · ${b.id_verified ? 'ID verified' : 'ID not verified'}</small></td>
            <td>${esc(DEP_ST[b.deposit_status] || b.deposit_status)}${b.deposit_ref ? `<br><small>Txn ${esc(b.deposit_ref)}</small>` : ''}${b.deposit_status === 'submitted' || b.deposit_status === 'paid' ? `<br><small class="${b.deposit_matched ? 'ok' : ''}">${b.deposit_matched ? '✓ matched to bank' : 'not matched to bank yet'}</small>` : ''}${b.deposit_proof ? `<br><button type="button" class="link-button" data-vfa="idfile" data-path="${esc(b.deposit_proof)}">Receipt</button>` : ''}</td>
            <td>${esc(REG_ST[b.status])}${b.note ? `<br><small>${esc(b.note)}</small>` : ''}</td>
            <td class="ax-dec"><select data-ax-dep>${['not_required', 'awaiting', 'submitted', 'paid', 'refunded', 'forfeited'].map((x) => `<option value="${x}" ${b.deposit_status === x ? 'selected' : ''}>${esc(DEP_ST[x])}</option>`).join('')}</select><input data-ax-note placeholder="Note / reason" maxlength="300" data-ax-keep="n-${esc(b.id)}"><div><button type="button" class="link-button" data-axa="bidder" data-st="approved" data-id="${esc(b.id)}">Approve</button> <button type="button" class="link-button" data-axa="bidder" data-st="${b.status === 'approved' ? 'suspended' : 'rejected'}" data-id="${esc(b.id)}">${b.status === 'approved' ? 'Suspend' : 'Reject'}</button> <button type="button" class="link-button" data-axa="bidder" data-st="${esc(b.status)}" data-id="${esc(b.id)}">Save deposit</button></div></td></tr>`).join('')}</tbody></table>` : '<p class="gw-mini">No bidders registered yet.</p>'}
          <h4>Bids (${a.bid_list.length})</h4>${a.bid_list.length ? `<table class="gw-table"><thead><tr><th>Time</th><th>Bidder</th><th>Amount</th><th></th></tr></thead><tbody>${a.bid_list.map((x) => `<tr class="${x.voided ? 'ax-void' : ''}"><td>${esc(new Date(x.at).toLocaleString('en-GB', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', second: '2-digit' }))}${x.extended ? ' <small>+time</small>' : ''}</td><td>Bidder ${esc(x.no)}<br><small>${esc(x.name || '')}</small></td><td>${esc(rs(x.amount))}${x.voided ? `<br><small>VOID: ${esc(x.void_reason)}</small>` : ''}</td><td>${!x.voided && ['live', 'closing', 'ended', 'provisional', 'reserve_not_met'].includes(a.phase) ? `<button type="button" class="link-button" data-axa="void" data-id="${esc(x.id)}">Void…</button>` : ''}</td></tr>`).join('')}</tbody></table>` : '<p class="gw-mini">No bids yet.</p>'}
          <div class="button-row ax-end">${['provisional'].includes(a.phase) ? `<button type="button" class="button button-primary" data-axa="result" data-r="sold" data-id="${k}">Confirm sale completed</button><button type="button" class="button button-outline" data-axa="result" data-r="failed" data-id="${k}">Winner did not complete</button>` : ''}${['provisional', 'reserve_not_met'].includes(a.phase) ? `<button type="button" class="button button-outline" data-axa="result" data-r="ended" data-id="${k}">Close without sale</button>` : ''}${['requested', 'upcoming', 'live', 'closing', 'provisional'].includes(a.phase) ? `<button type="button" class="button button-outline ax-danger" data-axa="cancel" data-id="${k}">Cancel auction…</button>` : ''}<button type="button" class="button button-outline" data-ax-open="${k}">Open auction room</button></div>
        </div></details>`; }).join('') : '<div class="admin-empty sm">Nothing here.</div>'}</div>`;
  }

  // ---------- Events ----------
  document.addEventListener('click', async (e) => {
    const o = e.target.closest('[data-ax-open]'); if (o && !e.target.closest('[data-ax], [data-axa]')) { e.preventDefault(); if ($('.modal-backdrop')) closeModal(); openAuction(o.dataset.axOpen); return; }
    const b = e.target.closest('[data-ax]');
    if (b) {
      const a = b.dataset.ax; if (b.tagName === 'A') e.preventDefault();
      if (a === 'home') { if ($('.modal-backdrop')) closeModal(); openAuctions(); }
      else if (a === 'tab') { ax.tab = b.dataset.v; auPaintHome(b.closest('.modal-card') || document); }
      else if (a === 'how') { const h = $('.ax-how'); if (h) h.hidden = !h.hidden; }
      else if (a === 'sell') { if ($('.modal-backdrop')) closeModal(); if (pf.my.open) closeMy(); openAuctionRequest(b.dataset.id); }
      else if (a === 'register') requireSignIn(() => auRefreshOpen());
      else if (a === 'watch') requireSignIn(async () => { try { const on = await AU.watch(b.dataset.id); toast(on ? 'Reminders on — we will notify you before it starts and before it ends.' : 'Reminders off.'); auRefreshOpen(); } catch (err) { toast(err.message); } });
      else if (a === 'quick') { const i = $('[data-ax-bid] [name=amount]'); if (i) { i.value = b.dataset.v; i.focus(); } }
      else if (a === 'withdraw') { if (!confirm('Withdraw this auction request?')) return; try { await AU.withdraw(b.dataset.id); toast('Auction withdrawn.'); if (LIVE) await backend.reloadListings(); auLoad(); renderMy(); } catch (err) { toast(err.message); } }
      return;
    }
    const x = e.target.closest('[data-axa]'); if (!x) return; const a = x.dataset.axa;
    const reload = () => { ax.admin = null; auAdminLoad(); auLoad().then(() => coreRails()); };
    if (a === 'reload') reload();
    else if (a === 'filter') { ax.adminFilter = x.dataset.v; const body = ($('.ax-body', admin.el) || $('.admin-content', admin.el)); if (body) body.innerHTML = auAdminHTML(); }
    else if (a === 'bidder') { const row = x.closest('tr'); const note = $('[data-ax-note]', row).value.trim(); const dep = $('[data-ax-dep]', row).value; const done = busy(x, '…'); try { await AU.bidder(x.dataset.id, x.dataset.st, dep, note, note); toast('Saved — the bidder has been notified.'); reload(); } catch (err) { done(); toast(err.message); } }
    else if (a === 'void') { const reason = prompt('Why is this bid being voided? (kept in the audit log)'); if (!reason) return; try { await AU.voidBid(Number(x.dataset.id) || x.dataset.id, reason); toast('Bid voided — the highest bid was recalculated.'); reload(); } catch (err) { toast(err.message); } }
    else if (a === 'cancel') { const reason = prompt('Reason for cancelling (shown to the seller and bidders, kept in the audit log):'); if (!reason) return; try { await AU.cancel(x.dataset.id, reason); toast('Auction cancelled.'); if (LIVE) await backend.reloadListings(); reload(); } catch (err) { toast(err.message); } }
    else if (a === 'result') { const reason = prompt({ sold: 'Confirm: agreement signed and payment received? Write a short note (kept in the audit log):', failed: 'What happened? (the winner\'s deposit will be marked forfeited)', ended: 'Reason for closing without a sale:' }[x.dataset.r]); if (!reason) return; try { await AU.result(x.dataset.id, x.dataset.r, reason); toast('Saved.'); if (LIVE) await backend.reloadListings(); reload(); } catch (err) { toast(err.message); } }
  });
  document.addEventListener('keydown', (e) => { if ((e.key === 'Enter' || e.key === ' ') && e.target.matches('.ax-card[data-ax-open]')) { e.preventDefault(); e.target.click(); } });
  document.addEventListener('change', (e) => { const f = e.target.closest('[data-ax-dep] [name=proof]'); if (f) { const s = $('[data-ax-file]'); if (s) s.textContent = f.files[0] ? f.files[0].name : 'Photo or PDF'; } });
  document.addEventListener('submit', async (e) => {
    const f = e.target;
    if (f.matches('[data-ax-reg]')) { e.preventDefault(); if (!f.terms.checked) { toast('Please accept the auction terms.'); return; } const done = busy($('[type=submit]', f), 'Registering…'); try { const b = await AU.register(f.dataset.id); toast(`Registered as Bidder ${b.bidder_no}.`); auRefreshOpen(); } catch (err) { done(); toast(err.message); } }
    else if (f.matches('[data-ax-dep]')) { e.preventDefault(); const done = busy($('[type=submit]', f), 'Sending…'); try { let path = ''; const file = f.proof.files[0]; if (file) { let x = file; if (/^image\//.test(x.type)) { try { x = await shrinkImage(x, 2000, 0.85); } catch { /* keep */ } } path = await PF.uploadId(x); } await AU.deposit(f.dataset.id, f.ref.value.trim(), path); toast('Deposit details sent. RAQBO will confirm it and approve your registration.'); auRefreshOpen(); } catch (err) { done(); toast(err.message); } }
    else if (f.matches('[data-ax-bid]')) {
      e.preventDefault(); const amount = Math.round(Number(f.amount.value)); const st = ax.state || {};
      if (!(amount >= (st.min_bid || 0))) { toast(`The minimum bid is ${rs(st.min_bid)}.`); return; } if (st.high_amount && (amount - st.high_amount) % st.increment) { toast(`Bids go up in steps of ${rs(st.increment)}. Try ${rs(st.min_bid)} or ${rs(st.min_bid + st.increment)}.`); return; }
      if (!confirm(`Place a bid of ${rs(amount)}?\n\nBids cannot be withdrawn. If you win, a ${st.buyer_premium_pct}% buyer's premium applies.`)) return;
      const done = busy($('[type=submit]', f), 'Placing bid…');
      try { const r = await AU.bid(f.dataset.id, amount); toast(`Bid placed: ${rs(r.amount)}${r.extended ? ' — the auction was extended' : ''}.`); await auRefreshOpen(); auLoad(); } catch (err) { done(); toast(err.message); auRefreshOpen(); }
    } else if (f.matches('[data-ax-request]')) {
      e.preventDefault(); const v = (n) => f.elements[n].value.trim(); const errs = []; const sp = Math.round(+v('starting_price') || 0); const rp = v('reserve_price') ? Math.round(+v('reserve_price')) : null;
      if (sp < 100000) errs.push(['starting_price', 'Enter a starting bid of at least Rs 100,000.']); if (rp && rp < sp) errs.push(['reserve_price', 'The reserve cannot be lower than the starting bid.']); if (showErrors(f, errs)) return;
      const done = busy($('[type=submit]', f), 'Sending…');
      try { const ref = await AU.request(v('lid'), { starting_price: sp, reserve_price: rp, preferred_start: v('preferred_start') || null, duration_days: +v('duration_days'), inspection_info: v('inspection_info'), seller_note: v('seller_note') }); done(); closeModal(); toast(`Auction request ${ref || ''} sent. RAQBO will review it and agree the schedule with you.`); openMy('auctions'); }
      catch (err) { done(); showErrors(f, [['starting_price', err.message]]); }
    } else if (f.matches('[data-axa-save]')) {
      e.preventDefault(); const act = (e.submitter && e.submitter.value) || 'save'; const el = f.elements; const val = (n) => (el[n] ? el[n].value.trim() : '');
      const toIso = (s) => (s ? new Date(s).toISOString() : '');
      const p = { action: act, starting_price: val('starting_price'), reserve_price: val('reserve_price'), increment: val('increment'), deposit: val('deposit'), start_at: toIso(val('start_at')), end_at: toIso(val('end_at')), ext_window_min: val('ext_window_min'), ext_min: val('ext_min'), max_extensions: val('max_extensions'), buyer_premium_pct: val('buyer_premium_pct'), seller_commission_pct: val('seller_commission_pct'), inspection_info: val('inspection_info'), terms: val('terms'), admin_note: val('admin_note') };
      if (act === 'reject' && !p.admin_note) { toast('Write the reason in “Note to the seller”.'); return; }
      const btn = e.submitter || $('[type=submit]', f); const done = busy(btn, '…');
      try { await AU.save(f.dataset.id, p, val('reason') || (act === 'reject' ? p.admin_note : act === 'approve' ? 'Approved after reviewing the property, documents and schedule' : 'Auction settings updated before bidding')); toast(act === 'approve' ? 'Auction approved and scheduled.' : act === 'reject' ? 'Request rejected — the seller has been notified.' : 'Saved.'); if (LIVE) await backend.reloadListings(); reload2(); } catch (err) { done(); toast(err.message); }
    }
  });
  function reload2() { ax.admin = null; auAdminLoad(); auLoad().then(() => { coreRails(); if (db.loaded) renderGrid(); }); }

  // ---------- Property page box ----------
  function auDetailBox(l) {
    const a = ax.byListing.get(l.id); if (!a || l.status !== 'published') return '';
    return `<section class="pp-section"><div class="ax-pbox"><div><span class="ax-tagx">${DI(DIC.gavel, 13)} ${a.phase === 'upcoming' ? 'AUCTION SOON' : ['live', 'closing'].includes(a.phase) ? 'LIVE AUCTION' : 'AUCTION'}</span><b>${a.high_amount ? 'Current bid ' + esc(rs(a.high_amount)) : 'Starting bid ' + esc(rs(a.starting_price))}</b><small>${esc(a.bid_count)} bids · ${auClock(a)}</small></div><button type="button" class="button button-primary" data-ax-open="${esc(a.id)}">${['live', 'closing'].includes(a.phase) ? 'Bid now' : 'Open auction'}</button></div></section>`;
  }
  function auRoute(h) { let m; if (h === '#auctions') { openAuctions(); return true; } if ((m = h.match(/^#auction\/(.+)$/))) { openAuction(decodeURIComponent(m[1])); return true; } if (h === '#admin/auctions') { openAdmin('auctions'); return true; } return false; }
  const axLive = () => ax.list.filter((a) => a.phase === 'live' || a.phase === 'closing').sort((x, y) => Date.parse(x.end_at) - Date.parse(y.end_at));
  const axSoon = () => ax.list.filter((a) => a.phase === 'upcoming').sort((x, y) => Date.parse(x.start_at) - Date.parse(y.start_at));
  RAILS.push(() => auOn() ? { id: 'rail-auctions', kicker: 'LIVE AUCTIONS', live: axLive().length > 0, title: axLive().length ? 'Live auctions — bid now' : 'Live auctions', sub: 'Verified bidders, anonymous bidder numbers and automatic extra time for last-minute bids.', list: axLive(), html: axLive().slice(0, 10).map(auCard).join(''), empty: `No auction is live right now${axSoon().length ? ' — see the upcoming auctions below' : ''}. <button type="button" class="link-button" data-ax="home">All auctions</button> · <button type="button" class="link-button" data-ax="sell">Sell by auction →</button>`, action: ['All auctions', 'auctions'] } : null);
  RAILS.push(() => auOn() && axSoon().length ? { id: 'rail-auctions-soon', kicker: 'UPCOMING AUCTIONS', title: 'Upcoming auctions', sub: 'Register early, inspect the property and turn on reminders.', list: axSoon(), html: axSoon().slice(0, 10).map(auCard).join(''), action: ['All auctions', 'auctions'] } : null);

